DROP TABLE IF EXISTS `im_conversation_read`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `im_conversation_read` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `user_id` bigint NOT NULL COMMENT '用户编号',
  `conversation_type` tinyint NOT NULL COMMENT '会话类型：1 私聊 2 群聊 3 频道',
  `target_id` bigint NOT NULL COMMENT '目标编号：私聊为对端用户编号，群聊为群编号，频道为频道编号',
  `message_id` bigint NOT NULL COMMENT '最大已读消息编号',
  `read_time` datetime NOT NULL COMMENT '最近已读时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_im_conversation_read_user_target` (`tenant_id`,`user_id`,`conversation_type`,`target_id`) USING BTREE,
  KEY `idx_im_conversation_read_target` (`conversation_type`,`target_id`,`message_id`) USING BTREE,
  KEY `idx_sync` (`user_id`,`update_time`,`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='IM 会话读位置表';
