--
-- Table structure for table `im_friend_request`
--

DROP TABLE IF EXISTS `im_friend_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `im_friend_request` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `from_user_id` bigint NOT NULL COMMENT '发起方用户编号',
  `to_user_id` bigint NOT NULL COMMENT '接收方用户编号',
  `handle_result` tinyint NOT NULL DEFAULT '0' COMMENT '处理结果；0未处理；1同意；2拒绝',
  `apply_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请理由（发起方填写）',
  `handle_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理理由（接收方拒绝时可选填）',
  `display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发起方对接收方的备注；同意后写入 A 侧 im_friend.display_name',
  `add_source` tinyint DEFAULT NULL COMMENT '添加来源；参见 ImFriendAddSourceEnum 枚举',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_im_friend_request` (`from_user_id`,`to_user_id`,`tenant_id`) USING BTREE,
  KEY `idx_to_user_handle` (`to_user_id`,`handle_result`) USING BTREE,
  KEY `idx_from_user` (`from_user_id`) USING BTREE,
  KEY `idx_sync_from` (`from_user_id`,`update_time`,`id`) USING BTREE,
  KEY `idx_sync_to` (`to_user_id`,`update_time`,`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IM 好友申请记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `im_friend_request`
--

LOCK TABLES `im_friend_request` WRITE;
/*!40000 ALTER TABLE `im_friend_request` DISABLE KEYS */;
INSERT INTO `im_friend_request` VALUES (6,1,103,1,'我是\"IM 联调测试群\"的芋道源码',NULL,NULL,2,'2026-05-04 11:00:34','1','2026-05-04 10:31:28','103','2026-05-04 11:00:34',0x00,1);
/*!40000 ALTER TABLE `im_friend_request` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `im_group`
--

DROP TABLE IF EXISTS `im_group`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `im_group` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群名称',
  `owner_user_id` bigint NOT NULL COMMENT '群主用户编号',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群头像',
  `notice` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群公告',
  `banned` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否封禁',
  `banned_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封禁原因',
  `banned_time` datetime DEFAULT NULL COMMENT '封禁时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '群状态 0=正常 1=已解散',
  `dissolved_time` datetime DEFAULT NULL COMMENT '解散时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
