--
-- Table structure for table `im_group_member`
--

DROP TABLE IF EXISTS `im_group_member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `im_group_member` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `group_id` bigint NOT NULL COMMENT '群编号',
  `user_id` bigint NOT NULL COMMENT '用户编号',
  `display_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组内显示名',
  `group_remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群备注',
  `silent` bit(1) DEFAULT b'0' COMMENT '是否免打扰',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '成员状态',
  `join_time` datetime DEFAULT NULL COMMENT '入群时间',
  `add_source` tinyint DEFAULT NULL COMMENT '加入来源；参见 ImGroupAddSourceEnum',
  `inviter_user_id` bigint DEFAULT NULL COMMENT '邀请人用户编号；主动申请进群时为 NULL',
  `quit_time` datetime DEFAULT NULL COMMENT '退群时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `role` tinyint NOT NULL DEFAULT '3' COMMENT '成员角色',
  `mute_end_time` datetime DEFAULT NULL COMMENT '禁言到期时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_im_group_member_group_user` (`group_id`,`user_id`) USING BTREE,
  KEY `idx_im_group_member_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IM 群成员表';
/*!40101 SET character_set_client = @saved_cs_client */;

